public class Main {
    private static final FastScanner fs = new FastScanner();
    private static final PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) {
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] a = new int[m];
        int[] b = new int[m];
        for (int i = 0; i < m; i++) {
            a[i] = fs.nextInt();
            b[i] = fs.nextInt();
        }

        // Create list of pairs to sort by b (matches per box) ascending
        // C# Array.Sort(b, a) sorts b ascending and moves a accordingly.
        // The C# loop iterates from m-1 down to 0 (descending b).
        Integer[] indices = new Integer[m];
        for (int i = 0; i < m; i++) indices[i] = i;
        Arrays.sort(indices, Comparator.comparingInt(i -> b[i]));

        long sum = 0;
        for (int idx = m - 1; idx >= 0; idx--) {
            int i = indices[idx];
            if (a[i] < n) {
                sum += (long) a[i] * b[i];
                n -= a[i];
            } else {
                sum += (long) n * b[i];
                break;
            }
        }

        out.println(sum);
        out.flush();
    }

    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        int nextInt() {
            return Integer.parseInt(next());
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024 * 10];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return 0;
            } while (c <= ' ');

            int res = 0;
            do {
                res = res * 10 + (c - '0');
                c = read();
            } while (c >= '0' && c <= '9');
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out), 1024 * 10);

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[][] boxes = new int[m][2];
        for (int i = 0; i < m; i++) {
            boxes[i][0] = fs.nextInt();
            boxes[i][1] = fs.nextInt();
        }

        Arrays.sort(boxes, Comparator.comparingInt(o -> o[1]));

        long sum = 0;
        for (int i = m - 1; i >= 0; i--) {
            int count = boxes[i][0];
            int matches = boxes[i][1];
            if (count < n) {
                sum += (long) count * matches;
                n -= count;
            } else {
                sum += (long) n * matches;
                break;
            }
        }

        bw.write(Long.toString(sum));
        bw.newLine();
        bw.flush();
    }
}

